//
// channel/keep-list.txt of Open-Mixer/.github, read by the prune: the versions our own work pins (generated by
// that repository's channel/gen-keep-list.mjs, never by hand). Lines are "<package> <version> <distro/arch> <pin>",
// tab separated; see the generator for the version forms. This module
//   - refuses a file whose lines do not match its "# sum" (a hand edit, or a generator bypassed),
//   - reads a pending:>=floor line (a floor on a package the channel serves nowhere yet) as pending: named, never a refusal,
//   - turns exact lines into keep entries (the prune keeps those builds beside the newest ones),
//   - names every line the channel does not serve (a missing pin: the channel lost, or never had, a version a
//     pin still names).
import crypto from 'node:crypto';
import { rpmvercmp, debVersionCmp, parseDebVersion, sourceName, whereMatches } from './prune.mjs';

export function parseKeepList(text) {
  const lines = [];
  let sum = null, header = false;
  for (const raw of text.split('\n')) {
    if (!raw.trim()) continue;
    const m = raw.match(/^# sum ([0-9a-f]{64})$/);
    if (m) { sum = m[1]; continue; }
    if (raw.startsWith('#')) { if (/^# GENERATED by channel\/gen-keep-list\.mjs/.test(raw)) header = true; continue; }
    const f = raw.split('\t');
    if (f.length !== 4 || f.some((x) => !x.trim())) throw new Error(`keep-list: not "package<TAB>version<TAB>distro/arch<TAB>pin": ${JSON.stringify(raw)}`);
    // pending:>=floor is a floor on a package the channel serves nowhere yet; it is read as the floor, marked pending
    const pending = f[1].startsWith('pending:');
    if (pending) f[1] = f[1].slice(8);
    if (!/^(newest|>=\S+|\d\S*)$/.test(f[1]) || (pending && !f[1].startsWith('>='))) throw new Error(`keep-list: bad version ${JSON.stringify(f[1])} in ${JSON.stringify(raw)}`);
    lines.push({ pkg: f[0], version: f[1], where: f[2], pin: f[3], pending });
  }
  if (!header) throw new Error('keep-list: no GENERATED header: the file is made by channel/gen-keep-list.mjs');
  const want = crypto.createHash('sha256').update(lines.map((l) => [l.pkg, (l.pending ? 'pending:' : '') + l.version, l.where, l.pin].join('\t')).join('\n') + '\n').digest('hex');
  if (sum !== want) throw new Error('keep-list: the lines do not match the "# sum": edited by hand, or not made by the generator');
  return lines;
}

const distroRepo = (where) => where.split('/').slice(0, 2).join('/'); // fedora/44/* -> fedora/44, debian/bookworm/amd64 -> debian/bookworm
const formatOf = (where) => (where.startsWith('fedora') ? ['rpm'] : where.startsWith('debian') ? ['deb'] : ['rpm', 'deb']);
const whereRepo = (where) => { const r = distroRepo(where); return r.endsWith('/*') || r === '*' ? r.replace(/\/?\*$/, '') || '*' : r; };

// exact lines -> keep entries
export function keepEntries(lines) {
  const out = [];
  for (const l of lines) {
    if (l.version === 'newest' || l.version.startsWith('>=')) continue;
    const [version, ...rel] = l.version.split(/-(.*)/s);
    const e = { version, where: whereRepo(l.where), reason: `${l.pin}` };
    if (rel[0]) e.release = rel[0];
    if (l.pkg.startsWith('source:')) e.source = [l.pkg.slice(7)];
    else for (const f of formatOf(l.where)) e[f] = [l.pkg];
    out.push(e);
  }
  return out;
}

const upstream = (p) => (p.format === 'rpm' ? p.evr.ver : parseDebVersion(p.evr).upstream);
const releaseOf = (p) => (p.format === 'rpm' ? p.evr.rel : parseDebVersion(p.evr).revision);
const vcmp = (p, v) => (p.format === 'rpm' ? rpmvercmp(upstream(p), v) : debVersionCmp(upstream(p), v));

// the builds of l's package the channel serves (every version, every cell the line names)
function served(l, allPkgs) {
  const archOk = (p) => { const a = l.where.split('/')[2]; return !a || a === '*' || p.arch === a || p.arch === 'noarch' || p.arch === 'all'; };
  return allPkgs.filter((p) => p.arch !== 'src' && formats(l).includes(p.format) && whereMatches(whereRepo(l.where), p.repo) && archOk(p)
    && (l.pkg.startsWith('source:') ? sourceName(p) === l.pkg.slice(7) : p.name === l.pkg));
}

// the lines the channel cannot serve: allPkgs are every package of every repository read. A line marked pending
// (a floor the generator saw unserved) stays pending only while no build of that package is served at all; once any
// version is served it is judged as an ordinary floor, so a package served only BELOW the floor is a missing pin
// (refused), and one at or above it is satisfied.
const isPending = (l, allPkgs) => l.pending && served(l, allPkgs).length === 0;
export const missing = (lines, allPkgs) => unserved(lines.filter((l) => !isPending(l, allPkgs)), allPkgs);
export const pendingPins = (lines, allPkgs) => unserved(lines.filter((l) => isPending(l, allPkgs)), allPkgs);

// the builds of l's package that satisfy it: any for newest, those at or above a floor, the exact version otherwise
function satisfiers(l, allPkgs) {
  const mine = served(l, allPkgs);
  if (l.version === 'newest') return mine;
  if (l.version.startsWith('>=')) return mine.filter((p) => vcmp(p, l.version.slice(2)) >= 0);
  const [v, ...r] = l.version.split(/-(.*)/s);
  return mine.filter((p) => upstream(p) === v && (!r[0] || releaseOf(p) === r[0] || releaseOf(p).startsWith(r[0] + '.')));
}

function unserved(lines, allPkgs) {
  const out = [];
  for (const l of lines) {
    if (!satisfiers(l, allPkgs).length) out.push(`${l.pkg} ${l.version} ${l.where}: the channel serves no such version (pin: ${l.pin})`);
  }
  return out;
}

// The floor and newest lines (the ones keepEntries does not turn into keep entries, so pinsLost cannot see them) that
// the channel serves before the plan and that no build the plan keeps satisfies: the plan takes away the last build of
// a pin. keptPaths holds "<format>/<repo>/<file>" of every kept package. Each is named with its pin and the builds the
// plan deletes, in the form of pinsLost's lines, so select.mjs reports both alike: an override a drop names, else a
// refusal. A line never served is missing(), not this.
export function pinsUnsatisfied(lines, allPkgs, keptPaths) {
  const out = [];
  const pathOf = (p) => `${p.format}/${p.repo}/${p.file}`;
  for (const l of lines) {
    if (l.version !== 'newest' && !l.version.startsWith('>=')) continue;
    const before = satisfiers(l, allPkgs);
    if (!before.length || before.some((p) => keptPaths.has(pathOf(p)))) continue;
    const gone = before.map((p) => `${p.name} ${upstream(p)}-${releaseOf(p)} ${p.repo}/${p.arch}`).sort();
    out.push(`${l.pkg} ${l.version} ${l.where}: the plan keeps no build that satisfies it (pin: ${l.pin}); it deletes ${gone.join(', ')}`);
  }
  return out;
}
const formats = (l) => formatOf(l.where);
